// Enriquece el payload con datos formateados para el email.
const payload = $input.first().json.body || $input.first().json;
const event = payload.event || 'created';
const a = payload.appointment || {};
const md = payload.metadata || {};

const eventEmoji = {
  created:   '🆕',
  confirmed: '✅',
  cancelled: '❌',
  attended:  '✨',
  updated:   '🔄',
  deleted:   '🗑️',
};
const eventTitle = {
  created:   'Cita agendada',
  confirmed: 'Cita confirmada',
  cancelled: 'Cita cancelada',
  attended:  'Cita atendida',
  updated:   'Cita actualizada',
  deleted:   'Cita eliminada',
};

const emailSubject = `${eventEmoji[event] || '📅'} ${eventTitle[event] || 'Notificación'} — ${a.clientName || 'Cliente'}`;

const emailBody = `
<div style="font-family: system-ui, -apple-system, sans-serif; max-width: 600px; margin: 0 auto; padding: 0; background: #1a1a1a;">
  <div style="background: linear-gradient(135deg, #2ba89a 0%, #d97706 100%); padding: 32px 24px; text-align: center; border-radius: 12px 12px 0 0;">
    <div style="font-size: 48px; margin-bottom: 8px;">💈</div>
    <h1 style="color: white; margin: 0; font-size: 28px;">${eventEmoji[event] || '📅'} ${eventTitle[event] || 'Notificación'}</h1>
    <p style="color: rgba(255,255,255,0.9); margin: 8px 0 0 0; font-size: 14px;">BarberSchedule</p>
  </div>

  <div style="background: #1a1a1a; padding: 32px 24px; color: #f5f5f5;">
    <p style="font-size: 16px; margin-top: 0;">Hola <strong style="color: #fbbf24;">${a.clientName || 'Cliente'}</strong>,</p>

    ${event === 'created' ? '<p>Tu cita en BarberSchedule está confirmada. Aquí tienes los detalles:</p>' : ''}
    ${event === 'confirmed' ? '<p>¡Buenas noticias! Tu cita ha sido confirmada:</p>' : ''}
    ${event === 'cancelled' ? '<p>Lamentamos informarte que tu cita fue cancelada.</p>' : ''}
    ${event === 'attended' ? '<p>¡Gracias por tu visita! Esperamos que te haya encantado.</p>' : ''}
    ${event === 'updated' ? '<p>Tu cita fue actualizada con los siguientes datos:</p>' : ''}

    <table style="width: 100%; border-collapse: collapse; margin: 24px 0; background: #262626; border-radius: 8px; overflow: hidden;">
      <tr>
        <td style="padding: 14px 16px; color: #999; border-bottom: 1px solid #333; width: 40%;">📅 Fecha</td>
        <td style="padding: 14px 16px; color: #f5f5f5; font-weight: 600; border-bottom: 1px solid #333;">${a.date || '—'}</td>
      </tr>
      <tr>
        <td style="padding: 14px 16px; color: #999; border-bottom: 1px solid #333;">⏰ Hora</td>
        <td style="padding: 14px 16px; color: #f5f5f5; font-weight: 600; border-bottom: 1px solid #333;">${a.time || '—'}</td>
      </tr>
      <tr>
        <td style="padding: 14px 16px; color: #999; border-bottom: 1px solid #333;">📞 Teléfono</td>
        <td style="padding: 14px 16px; color: #f5f5f5; border-bottom: 1px solid #333;">${a.phone || '—'}</td>
      </tr>
      <tr>
        <td style="padding: 14px 16px; color: #999;">✂️ Notas</td>
        <td style="padding: 14px 16px; color: #f5f5f5;">${a.notes || 'sin notas'}</td>
      </tr>
    </table>

    <div style="background: #262626; border-left: 4px solid #2ba89a; padding: 16px; border-radius: 4px; margin: 24px 0;">
      <p style="margin: 0; color: #f5f5f5;">${event === 'cancelled' ? 'Si quieres reagendar, entra a la app o contáctanos.' : '¡Te esperamos puntualmente! 💈'}</p>
    </div>

    <hr style="border: none; border-top: 1px solid #333; margin: 24px 0;">

    <p style="color: #888; font-size: 12px; text-align: center; margin: 0;">
      — Equipo de BarberSchedule 💈<br>
      <span style="color: #555;">Si tienes dudas, responde a este correo</span>
    </p>
  </div>
</div>
`;

return [{
  json: {
    event,
    appointment: a,
    metadata: md,
    emailSubject,
    emailBody,
  }
}];
